export const MOLFILE_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/molfile-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getMolfileStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(MOLFILE_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
